const opportunities = $input.all().map(i => i.json);
const now = Date.now();
const due = opportunities.filter(o => {
  if (['won','lost','nurture'].includes(o.status)) return false;
  if (!o.next_follow_up_at) return true;
  return new Date(o.next_follow_up_at).getTime() <= now;
});
return due.map(o => ({json: {...o, decision: 'send_follow_up'}}));

const o = $json;
const stage = o.status || 'new';
const attempts = Number(o.follow_up_count || 0);
let message;
if (stage === 'proposal_sent') {
  message = attempts === 0
    ? 'Hola, quería confirmar que recibiste la propuesta. Si hay alguna duda o algo que quieras revisar, lo vemos.'
    : 'Hola, quería saber qué te pareció la propuesta. Si hay algo que no termina de encajar con lo que buscabas, contame y vemos cómo ajustarlo.';
} else if (stage === 'contacted') {
  message = 'Hola, retomo el contacto para saber si pudiste revisar lo que conversamos. Si querés, podemos avanzar sobre el próximo paso.';
} else {
  message = 'Hola, retomo el contacto para saber si sigue siendo de interés avanzar con esto. Si cambió la prioridad, no hay problema.';
}
return [{json: {...o, outbound_message: message, next_action: 'send_message'}}];

const o = $json;
return [{json: {
  opportunity_id: o.id || null,
  channel: o.preferred_channel || 'whatsapp',
  action: 'send_message',
  message: o.outbound_message,
  requires_provider_credentials: true,
  status: 'ready_for_delivery'
}}];

const o = $json;
return [{json: {
  ...o,
  event: 'follow_up_ready',
  note: 'Connect WhatsApp/provider here before enabling outbound messaging.'
}}];
